19	const PROCESSING_FEE = 5;
20	const FIRST_INSURANCE_SURCHARGE = 0.1;
21	
22	const ITEM_BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	  moonstone: 25,
29	};
30	
31	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
32	
33	const BLOCK_SIZE = 3;
34	const BLOCK_BASE_PREMIUM = 60;
35	
36	const countByType = (items: Item[]): Map<string, number> => {
37	  const counts = new Map<string, number>();
38	  for (const item of items) {
39	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
40	  }
41	  return counts;
42	};
43	
44	const sumItemBasePremiums = (items: Item[]): number => {
45	  let total = 0;
46	  for (const [type, count] of countByType(items)) {
47	    total +=
48	      count === BLOCK_SIZE
49	        ? BLOCK_BASE_PREMIUM
50	        : count * ITEM_BASE_PREMIUMS[type];
51	  }
52	  return total;
53	};
54	
55	const quotePremium = (items: Item[]): number => {
56	  const policyBasePremium = sumItemBasePremiums(items);
57	  return roundInMHPCOsFavour(
58	    policyBasePremium +
59	      policyBasePremium * FIRST_INSURANCE_SURCHARGE +
60	      PROCESSING_FEE,
61	  );
62	};
63	
64	export const runScenario = (scenario: Scenario): ScenarioResults => {
65	  return {
66	    results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
67	  };
68	};
